VlMDsSJ5.css:
transition:
  opacity 160ms ease-out,
  translate 160ms ease-out,
  display 120ms allow-discrete;

@starting-style {
  opacity: 0;
  translate: 0 12px;
}

&[data-state="closed"] {
  display: none;
  opacity: 0;
  translate: 0 0;
  transition-duration: 120ms;
}

